import { GET } from '@/api/index'

/**
 * 协议类内容（注册协议 / 平台使用协议等）统一走系统配置接口，
 * 管理员在「系统配置」里维护富文本，前端拿不到配置时由调用方回退内置默认文案。
 */
const agreementPromises = new Map()

/**
 * 按系统配置键拉取协议富文本内容。
 * @param {string} configKey 系统配置键，如 platform.usage.agreement
 * @returns {Promise<string|null>} 配置的富文本；未配置 / 请求失败返回 null
 */
export function getAgreementContent(configKey) {
  const key = String(configKey || '').trim()
  if (!key) return Promise.resolve(null)
  if (agreementPromises.has(key)) {
    return agreementPromises.get(key)
  }
  const promise = GET(`/system/config/getByKey/${key}`, {}, { noMessage: true })
    .then((res) => {
      const text = String(res?.data ?? '').trim()
      if (!text) {
        // 未配置：不缓存，避免配置好后本轮会话一直回退
        agreementPromises.delete(key)
        return null
      }
      const settled = Promise.resolve(text)
      agreementPromises.set(key, settled)
      return text
    })
    .catch(() => {
      agreementPromises.delete(key)
      return null
    })
  agreementPromises.set(key, promise)
  return promise
}

